# shellcheck shell=bash
# WHICH MIGRATIONS THE FACTORY-CLEAN BASELINE ALREADY CONTAINS — read from the baseline itself.
#
# data-plane/migrations/baseline/0000_production_baseline.sql is generated by scripts/generate-production-baseline.sh
# from the END STATE of the upgrade path, and its header names the last migration that path held:
#
#     -- installations continue to upgrade through data-plane/migrations/0001..NNNN, which still create
#
# Every consumer used to hard-code that number instead. When migrations 0150..0158 were published and the
# baseline was not regenerated, the provisioner kept installing a 0149 schema while gatep-grants.sql (same
# revision) already granted on objects only 0155 creates — so a factory-clean install aborted half-way, and the
# test harnesses quietly papered over the gap with their own constant. Deriving the number from the file makes
# a stale baseline a loud, early, explainable refusal instead.
#
# Sourced. Pure: reads files, prints values, changes nothing.

# baseline_through <baseline.sql> -> the four-digit last migration the baseline embodies (empty if unreadable)
baseline_through() {
  sed -n 's#.*data-plane/migrations/0001\.\.\([0-9][0-9][0-9][0-9]\).*#\1#p' "$1" 2>/dev/null | head -1
}

# latest_migration <migrations dir> -> the four-digit number of the highest NNNN_*.up.sql in that directory
latest_migration() {
  ls "$1" 2>/dev/null | grep -E '^[0-9]{4}_.*\.up\.sql$' | sort | tail -1 | cut -c1-4
}

# migrations_after <migrations dir> <NNNN> -> every migration version strictly above NNNN, in order
migrations_after() {
  local f
  ls "$1" 2>/dev/null | grep -E '^[0-9]{4}_.*\.up\.sql$' | sort | while read -r f; do
    [ "${f:0:4}" \> "$2" ] && echo "${f%.up.sql}"
  done
  return 0
}

# baseline_is_current <baseline.sql> <migrations dir> -> 0 when the baseline embodies the newest migration.
# Prints the reason on failure.
baseline_is_current() {
  local have want
  have="$(baseline_through "$1")"
  want="$(latest_migration "$2")"
  if [ -z "$have" ]; then echo "the baseline $1 does not state which migrations it contains"; return 1; fi
  if [ -z "$want" ]; then echo "no numbered migrations found in $2"; return 1; fi
  if [ "$have" != "$want" ]; then
    echo "the baseline embodies migrations up to $have but the release ships up to $want; regenerate it with scripts/generate-production-baseline.sh"
    return 1
  fi
  return 0
}

# ---------------------------------------------------------------------------------------------------------------------
# RESERVED NUMBERS AND PINNED IDENTITIES (data-plane/migrations/RESERVED_NUMBERS and IDENTITIES).
#
# The SAME two files tools/validate-migration-location.py reads in CI are read here at apply time, so a file the
# validator would refuse cannot be applied on an appliance either (a release built from a branch that skipped CI, or a
# tree edited after installation).
#
#   reserved_number_list <dir>        every reserved four-digit number, one per line; return 2 on a malformed line
#   is_reserved_number <dir> <NNNN>   0 reserved · 1 not reserved · 2 the declaration is unreadable (callers fail closed)
#   release_identity_problems <dir>   prints one line per pinned migration whose file is missing or whose sha256 differs
# ---------------------------------------------------------------------------------------------------------------------
reserved_number_list() {
  local f="$1/RESERVED_NUMBERS" line range a b n
  [ -f "$f" ] || return 0
  while IFS= read -r line || [ -n "$line" ]; do
    line="${line%%#*}"
    range="$(printf '%s' "$line" | awk '{print $1}')"
    [ -n "$range" ] || continue
    if ! [[ "$range" =~ ^([0-9]{4})-([0-9]{4})$ ]]; then echo "RESERVED_NUMBERS: malformed line: $line" >&2; return 2; fi
    a=$((10#${BASH_REMATCH[1]})); b=$((10#${BASH_REMATCH[2]}))
    [ "$a" -le "$b" ] || { echo "RESERVED_NUMBERS: range runs backwards: $line" >&2; return 2; }
    for ((n=a; n<=b; n++)); do printf '%04d\n' "$n"; done
  done < "$f"
}

is_reserved_number() {
  local list
  list="$(reserved_number_list "$1")" || return 2
  printf '%s\n' "$list" | grep -qx "$2"
}

release_identity_problems() {
  local dir="$1" f stem want got
  [ -f "$dir/IDENTITIES" ] || return 0
  while read -r stem want; do
    case "$stem" in ''|'#'*) continue;; esac
    f="$dir/$stem.up.sql"
    if [ ! -f "$f" ]; then echo "$stem: pinned in IDENTITIES but the release has no such file"; continue; fi
    got="$(sha256sum "$f" | cut -d' ' -f1)"
    [ "$got" = "$want" ] || echo "$stem: sha256 $got differs from the pinned $want"
  done < "$dir/IDENTITIES"
}
